package org.apache.commons.lang3;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.ObjectStreamClass;
import java.io.OutputStream;
import java.io.Serializable;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.apache.commons.lang3.SerializationUtils.ClassLoaderAwareObjectInputStream;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class ClassLoaderAwareObjectInputStream_resolveClass_TriageGen1Test {

    /**
     * Helper method to access the protected resolveClass method via reflection.
     */
    @SuppressWarnings("unchecked")
    private Class<?> invokeResolveClass(ClassLoaderAwareObjectInputStream stream, ObjectStreamClass desc) throws Exception {
        Method method = ClassLoaderAwareObjectInputStream.class.getDeclaredMethod("resolveClass", ObjectStreamClass.class);
        method.setAccessible(true);
        return (Class<?>) method.invoke(stream, desc);
    }

    @Test
    public void testResolveClass_SuccessWithCustomClassLoader() throws Exception {
        // Arrange
        String className = "java.lang.String";
        ClassLoader customClassLoader = ClassLoader.getSystemClassLoader();
        InputStream is = new ByteArrayInputStream(new byte[0]);
        ClassLoaderAwareObjectInputStream stream = new ClassLoaderAwareObjectInputStream(is, customClassLoader);

        ObjectStreamClass desc = mock(ObjectStreamClass.class);
        when(desc.getName()).thenReturn(className);

        // Act
        Class<?> result = invokeResolveClass(stream, desc);

        // Assert
        assertEquals(String.class, result);
    }

    @Test
    public void testResolveClass_FallbackToContextClassLoader() throws Exception {
        // Arrange
        // We use a class that exists in the context class loader but NOT in our custom class loader.
        // Since we cannot easily create a "missing" class in a real ClassLoader without complex mocking,
        // we simulate the flow by providing a custom ClassLoader that returns null/throws for a specific name.

        String targetClass = "java.lang.Integer";

        ClassLoader emptyClassLoader = new ClassLoader() {
            @Override
            public Class<?> loadClass(String name) throws ClassNotFoundException {
                // Force ClassNotFoundException for the target class to trigger the catch block
                if (name.equals(targetClass)) {
                    throw new ClassNotFoundException(name);
                }
                return super.loadClass(name);
            }
        };

        InputStream is = new ByteArrayInputStream(new byte[0]);
        ClassLoaderAwareObjectInputStream stream = new ClassLoaderAwareObjectInputStream(is, emptyClassLoader);

        ObjectStreamClass desc = mock(ObjectStreamClass.class);
        when(desc.getName()).thenReturn(targetClass);

        // Act
        // This should trigger the catch block and use Thread.currentThread().getContextClassLoader()
        Class<?> result = invokeResolveClass(stream, desc);

        // Assert
        assertEquals(Integer.class, result);
    }

    @Test(expected = Exception.class)
    public void testResolveClass_ThrowsClassNotFoundException() throws Exception {
        // Arrange
        String nonExistentClass = "com.nonexistent.FakeClass";
        ClassLoader customClassLoader = ClassLoader.getSystemClassLoader();
        InputStream is = new ByteArrayInputStream(new byte[0]);
        ClassLoaderAwareObjectInputStream stream = new ClassLoaderAwareObjectInputStream(is, customClassLoader);

        ObjectStreamClass desc = mock(ObjectStreamClass.class);
        when(desc.getName()).thenReturn(nonExistentClass);

        // Act
        // This should throw ClassNotFoundException from both attempts
        invokeResolveClass(stream, desc);
    }
}

/**
 * Mocking ObjectStreamClass since it's part of java.io and often used in serialization tests.
 * Note: In a real environment, this is provided by the JDK.
 */
interface ObjectStreamClass {
    String getName();
}
